Rules.InvariantScript:
IfError(ClearCollect(colFicha, tblFichaDescarte), Notify("No se pudo leer la Ficha de Descarte: " & FirstError.Message, NotificationType.Error));
If(IsBlank(varRafaga), Set(varRafaga, false));
Set(varEditDs, false);
Set(varProcDs, false);
SetFocus(txtMasivoDs);
If(!varCargado,
    Concurrent(
        ClearCollect(colPersonal, tblPersonal),
        If(IsError(ClearCollect(colIngresos, tblIngresos)), false),
        ClearCollect(colHistorial, tblHistorial),
        ClearCollect(colDonantes, tblDonantes)
    );
    Set(varYo, LookUp(colPersonal, Lower(Trim(Correo)) = Lower(User().Email) && Activo = "Sí"));
    Set(varArea, If(IsBlank(varYo), "Sin acceso", varYo.Area));
    Set(varCargado, true)
);
If(IsBlank(varTema), Set(varTema, "claro"))

Set(varProcDs, true);
With({lineas: Filter(ForAll(Split(Substitute(txtMasivoDs.Text, Char(13), ""), Char(10)) As l,
        With({x: Trim(First(Split(l.Value, Char(9))).Value)}, {c: If(IsMatch(x, "^\d{1,5}$"), Right("000000" & x, 6), x)})), !IsBlank(c))},
    ClearCollect(colNuevosDs, Filter(Distinct(lineas, c), !(Value in colMasivo.codigo)))
);
ForAll(colNuevosDs As n,
    With({j: ParseJSON(IfError(Text('Copiade:BuscarLibroFOLIO'.Run(n.Value).datos), "{}"))},
        Collect(colMasivo, {
            codigo: n.Value,
            estado: If(n.Value in colFicha.'Codigo de Barra', "Ya registrado", Text(j.encontrado) = "SI", "Registrado", "Pendiente"),
            enc: Text(j.encontrado) = "SI",
            hrid: Text(j.hrid), copia: Text(j.copia), tipo: Text(j.tipo), ubicacion: Text(j.ubicacion), titulo: Text(j.titulo),
            autor: Text(j.autor), idioma: Text(j.idioma), fecha: Text(j.fecha), anio: Text(j.anio),
            exA: Coalesce(Value(j.exA), 0), exF: Coalesce(Value(j.exF), 0), exP: Coalesce(Value(j.exP), 0), exV: Coalesce(Value(j.exV), 0),
            pol: "", valor: "", cruce: "No esta en archivo", nodesc: "",
            vinculado: If(IsBlank(Text(j.vinculado)), "NO", Text(j.vinculado)),
            serie: Text(j.serie) = "SI",
            unidadAcad: If(IsBlank(Text(j.unidad)), "Desconocida", Text(j.unidad))
        })
    )
);
If(!IsEmpty(colNuevosDs), Set(varSelDs, Last(colNuevosDs).Value));
Set(varUltDs, txtMasivoDs.Text);
Set(varRevisadoDs, txtMasivoDs.Text);
Set(varProcDs, false);
If(varRafaga && !IsBlank(drpUnidadDescarte.Selected.Value) && !IsBlank(drpInventario.Selected.Value) && !IsBlank(drpCriterio.Selected.Value) && !IsBlank(drpJustificacion.Selected.Value) && CountRows(Filter(colMasivo, estado = "Registrado")) > 0, Select(btnGuardarDs))
